 const duplicateScene=(id=scene?.id)=>{const current=projectRef.current,target=current?.scenes.find(s=>s.id===id);if(!current||!target)return;if(current.scenes.length>=100){notify('El proyecto admite hasta 100 planos.');return}try{const nextId=uid();const next=duplicateSceneAttachments({...current,scenes:current.scenes.flatMap(s=>s.id===id?[s,{...structuredClone(s),id:nextId,title:`${s.title.slice(0,238)} · variante`}]:[s])},id!,nextId);update(()=>next);setSelectedId(nextId);setPlaying(false);setPlayhead((buildTimeline(current).segments.find(item=>item.scene.id===id)?.endFrame||0)/current.fps);notify('Variante creada; la toma original se conserva')}catch(error){fail(error)}};
 const removeScene=(id=scene?.id)=>{const current=projectRef.current;if(!current||!id)return;try{const index=current.scenes.findIndex(s=>s.id===id),cleaned=removeSceneAttachments(current,id),next=cleaned.scenes.filter(s=>s.id!==id),result={...cleaned,scenes:next};update(()=>result);setSelectedId(next[Math.min(index,next.length-1)]?.id||'');setPlayhead(shotStart(result,next[Math.min(index,next.length-1)]?.id));setPlaying(false);notify('Plano eliminado. Puedes deshacerlo.')}catch(error){fail(error)}};
 const moveScene=(id:string,target:number)=>{const current=projectRef.current;if(!current)return;const scenes=[...current.scenes],i=scenes.findIndex(s=>s.id===id);if(i<0)return;const at=Math.max(0,Math.min(target,scenes.length-1));if(i===at)return;const [moved]=scenes.splice(i,1);scenes.splice(at,0,moved);update(p=>({...p,scenes}));setPlaying(false);setSelectedId(id);setPlayhead(shotStart({...current,scenes},id))};
 const upload=async(files:FileList|File[],assignToScene=true)=>{if(!files.length)return;const projectId=projectRef.current?.id,targetSceneId=scene?.id;setBusy(true);try{await persist();if(projectRef.current?.id!==projectId)throw new Error('La película cambió. Vuelve a importar el material en el proyecto elegido.');const fd=new FormData();if(projectId)fd.append('projectId',projectId);Array.from(files).forEach(f=>fd.append('files',f));const d=await api('/assets',fd);const first=d.assets.find((a:Asset)=>a.type!=='audio');update(p=>{if(p.id!==projectId)return p;const assets=[...p.assets,...d.assets.filter((a:Asset)=>!p.assets.some(x=>x.id===a.id))];return {...p,assets,scenes:first&&targetSceneId&&assignToScene?p.scenes.map(s=>s.id===targetSceneId?assignScenePatch(s,first.type==='video'?{videoAssetId:first.id}:{assetId:first.id},assets):s):p.scenes}});notify(`${d.assets.length} archivo(s) incorporado(s). Originales conservados.`)}catch(e){fail(e)}finally{setBusy(false);if(fileRef.current)fileRef.current.value=''}};
 const generationSettings=generationPreview(model,generationDuration,scene?.duration??generationDuration,project?.format??'16:9',quality,longSteps,nativeResolution);
 const generationReferencesBlocked=generationSettings.supervised&&!!scene&&!!project&&longProfileReferenceConflict(scene,project);
 const generationBlocked=generationReferencesBlocked||!!generationSettings.blockedReason;
 const referenceProfileError='Este perfil supervisado sólo admite texto. Conserva las imágenes y referencias eligiendo Estándar y una duración de hasta 4 s.';
 const generationRequest=(seconds:number,mode=conditioningMode)=>{if(page==='studio'&&(!generationDraftValid||(generationSettings.long&&!generationSettings.native&&!stepsDraftValid)))throw new Error('Corrige la duración o los pasos antes de generar.');const profile=generationPreview(model,generationDuration,seconds,project?.format??'16:9',quality,longSteps,nativeResolution);if(profile.blockedReason)throw new Error(profile.blockedReason);return {model,width:profile.width,height:profile.height,steps:profile.steps,duration:profile.limit,conditioningMode:profile.supervised?'text':mode==='auto'?undefined:mode,...(profile.memoryProfile?{memoryProfile:profile.memoryProfile}:{})}};
 const generate=async(mode=conditioningMode)=>{if(!scene)return;const submissionKey=`${project?.id}:${scene.id}`;if(activeGeneration||generationSubmission.current===submissionKey){notify('Este plano ya tiene una toma en curso. Puedes seguirla en Actividad.');setPage('jobs');return}if(generationBlocked){notify(generationSettings.blockedReason??referenceProfileError);return}if(modelNeedsPreparation){setPage('engine');notify('Completa la preparación del modelo para generar este plano.');return}generationSubmission.current=submissionKey;setBusy(true);try{await persist();const result=await api('/generate',{sceneId:scene.id,...generationRequest(scene.duration,mode)});setJobs(current=>[result.job,...current.filter(job=>job.id!==result.job.id)]);notify('Plano enviado a la cola local');setPage('jobs')}catch(e){fail(e)}finally{if(generationSubmission.current===submissionKey)generationSubmission.current=null;setBusy(false)}};
 const generateVariants=async(count:number)=>{if(!scene)return;if(generationBlocked){notify(generationSettings.blockedReason??referenceProfileError);return}if(modelNeedsPreparation){setPage('engine');notify('Completa la preparación del modelo para crear tomas alternativas.');return}setBusy(true);try{await persist();const d=await api('/generate-variants',{sceneId:scene.id,...generationRequest(scene.duration),count});setJobs(j=>[...d.jobs.reverse(),...j]);notify(`${d.count} ${d.count===1?'toma añadida':'tomas añadidas'} a la cola. Podrás elegirlas aquí al terminar.`)}catch(e){fail(e)}finally{setBusy(false)}};
 const generateSequence=async()=>{if(generationSettings.blockedReason){notify(generationSettings.blockedReason);return}if(generationSettings.supervised&&project?.scenes.some(item=>!item.videoAssetId&&longProfileReferenceConflict(item,project))){notify(referenceProfileError);return}setBusy(true);try{await persist();const d=await api('/generate-sequence',{...generationRequest(generationDuration),onlyMissing:true});setJobs(j=>[...d.jobs.reverse(),...j]);setPage('jobs');notify(d.jobs.length?`${d.jobs.length} planos añadidos a la cola. Se generarán uno a uno.`:'Todos los planos ya tienen una toma asignada.')}catch(e){fail(e)}finally{setBusy(false)}};
 const changeProject=async(operation:()=>Promise<{project:Project}>,message:string)=>{
  if(projectTransition.current)return;
  projectTransition.current=true;syncEpoch.current++;setTransitioning(true);setPlaying(false);
  try{await persist();const d=await operation();if(saveTimer.current){clearTimeout(saveTimer.current);saveTimer.current=null}confirmedProject.current=d.project;projectRef.current=d.project;setProject(d.project);setSelectedId(d.project.scenes[0]?.id||'');setProjectsOpen(false);setNewOpen(false);updateHistory(emptyHistory());setPlayhead(0);setPage('home');setSaveState('saved');notify(message)}catch(e){fail(e)}finally{projectTransition.current=false;syncEpoch.current++;setTransitioning(false)}
 };
 const importProject=async(file:File)=>{try{await changeProject(()=>{const body=new FormData();body.append('projectFile',file);return api('/projects/import',body)},'Película importada con sus originales. El proyecto anterior queda guardado.')}finally{if(projectFileRef.current)projectFileRef.current.value=''}};
 const askCodex=async()=>{if(!codexPrompt.trim()||codexBusy)return;setCodexBusy(true);try{await persist();const d=await api('/codex',{task:codexTask,prompt:codexPrompt,sceneId:scene?.id});if(d.job)setJobs(j=>[d.job,...j]);setCodexPrompt('');notify('Codex está trabajando en tu proyecto')}catch(e){fail(e)}finally{setCodexBusy(false)}};
