 const downloadScript=()=>{const text=[project!.name.toUpperCase(),project!.logline,'',...project!.scenes.flatMap((s,i)=>[`${i+1}. ${s.title.toUpperCase()}`,s.description,'',s.dialogue,`[${s.duration}s · ${cinemaDirectionLabel(s)}]`,''])].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`${project!.name}.txt`;a.click();URL.revokeObjectURL(url)};
 const exportProject=async(format:string)=>{if(format==='mp4'&&exportResolution==='2160p'&&!continuityApproval){notify('Revisa la continuidad antes de exportar en 4K.');return}setBusy(true);try{await persist();const d=await api('/export',{format,...(format==='mp4'?{resolution:exportResolution,aiEnhance:exportResolution==='2160p'&&exportAi,strength:projectRef.current?.aiFinishing?.strength??.35,processingProfile:projectRef.current?.aiFinishing?.processingProfile??'conservative',...(exportResolution==='2160p'?{requireContinuityReview:true,...continuityApproval}:{})}:{})});if(d.url){const a=document.createElement('a');a.href=d.url;a.download='';a.click()}if(d.job){setJobs(j=>[d.job,...j]);setPage('jobs')}setExportOpen(false);notify(format==='mp4'?'Exportación iniciada':'Archivo de proyecto preparado')}catch(e){fail(e)}finally{setBusy(false)}};
 const createProject=()=>{if(!newName.trim()||!project)return;const next:Project={...project,library:undefined,audioMix:undefined,subtitleStyle:undefined,clipGroups:[],markers:[],story:undefined,id:uid(),name:newName.trim(),logline:'',audioAssetId:undefined,audioVolume:undefined,audioMuted:undefined,tracks:[],dialogueLines:[],subtitleCues:[],subtitlesEnabled:true,scenes:newKind==='ad'?['El gancho','El producto','La experiencia','La llamada a la acción'].map((title,i)=>({id:uid(),title,description:'',dialogue:'',prompt:'',negativePrompt:'',duration:i===0?3:5,seed:42,camera:cameras[0],characterIds:[]})):[],characters:[],assets:[],format:newKind==='ad'?'9:16':DEFAULT_PROJECT_FORMAT,fps:DEFAULT_PROJECT_FPS};void changeProject(()=>api('/project',next,'PUT'),'Nuevo proyecto creado. El anterior permanece en las copias del estudio.')};
 const exportText=async(kind:'edl'|'subtitles')=>{setBusy(true);try{await persist();const response=await fetch(`/api/project/${kind}`);if(!response.ok){const body=await response.json();throw new Error(body.error||'No se pudo preparar el archivo.')}const url=URL.createObjectURL(await response.blob());const link=document.createElement('a');link.href=url;link.download=`${projectRef.current?.name||'Filmma'}.${kind==='edl'?'edl':'srt'}`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Archivo preparado con el montaje guardado')}catch(e){fail(e)}finally{setBusy(false)}};
 const enhance=async(assetId:string,preset:EnhancementPreset,strength?:number,processingProfile:'conservative'|'restore'|'temporal'='conservative')=>{setBusy(true);try{await persist();const d=await api(`/assets/${encodeURIComponent(assetId)}/enhance`,{projectId:projectRef.current?.id,preset,...(preset==='ai-4k'?{strength,processingProfile}: {})});setJobs(j=>[d.job,...j]);notify('Mejora iniciada. La nueva versión aparecerá aquí al terminar.')}catch(e){fail(e)}finally{setBusy(false)}};
