function Modal({title,close,children}:{title:string;close:()=>void;children:ReactNode}){const ref=useRef<HTMLDivElement>(null);useEffect(()=>{const previous=document.activeElement as HTMLElement;const container=ref.current;const focusable=()=>Array.from(container?.querySelectorAll<HTMLElement>('button:not(:disabled),input,select,textarea,a[href]')||[]);focusable()[0]?.focus();const handler=(e:KeyboardEvent)=>{if(e.key==='Escape')close();if(e.key==='Tab'){const f=focusable(),first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};container?.addEventListener('keydown',handler);return()=>{container?.removeEventListener('keydown',handler);previous?.focus()}},[]);return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><motion.div ref={ref} role="dialog" aria-modal="true" aria-label={title} className="modal" initial={{y:16,opacity:0}} animate={{y:0,opacity:1}}><IconButton icon={X} label="Cerrar ventana" onClick={close}/><h2>{title}</h2>{children}</motion.div></div>}
